 "content": "def transform(grid):
    # Each 3x4 repeating tile contributes one cell. The interior fill is 7;
    # nonzero values on the divider lattice are encoded markers.
    h, w = len(grid), len(grid[0])
    return [[grid[3*r][4*c] or 7 for c in range(w // 4)]
            for r in range(h // 3)]
